-- Current legal-dong names for upload location autocomplete.
-- Source: Ministry of the Interior and Safety administrative standard code system,
-- full legal-dong dataset published 2026-07-08. Geometry is intentionally omitted.

create table if not exists public.administrative_areas (
  code text primary key check (code ~ '^[0-9]{10}$'),
  full_name text not null,
  leaf_name text not null,
  level text not null check (level in ('sido', 'sigungu', 'eup_myeon_dong', 'ri')),
  source_updated_on date not null,
  updated_at timestamptz not null default now()
);

create index if not exists administrative_areas_full_name_trgm_idx
  on public.administrative_areas using gin (full_name gin_trgm_ops);

create index if not exists administrative_areas_leaf_name_trgm_idx
  on public.administrative_areas using gin (leaf_name gin_trgm_ops);

alter table public.administrative_areas enable row level security;

revoke all on table public.administrative_areas from anon, authenticated;
grant all on table public.administrative_areas to service_role;

comment on table public.administrative_areas is
  'Current MOIS legal-dong hierarchy used for authenticated upload location suggestions. Refreshed from official full or incremental datasets.';

-- Seed rows are generated from the official current-only records below.

on conflict (code) do update set
  full_name = excluded.full_name,
  leaf_name = excluded.leaf_name,
  level = excluded.level,
  source_updated_on = excluded.source_updated_on,
  updated_at = now();

